def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    air = 7
    out = g.copy()
    comps = components(g != air)
    # split multicolour components into single-colour objects
    objs = []
    for c in comps:
        cols = {}
        for (y, x) in c:
            cols.setdefault(g[y, x], []).append((y, x))
        for col, cells in cols.items():
            for sub in components(np.isin(np.arange(H*W).reshape(H, W),
                                          [y*W+x for y, x in cells])):
                objs.append((col, sub))
    static = np.zeros((H, W), bool)
    movers = []
    for col, cells in objs:
        if any(y == H - 1 for y, x in cells):
            for y, x in cells:
                static[y, x] = True
        else:
            movers.append((col, cells))
    occupied = static.copy()
    for col, cells in movers:
        for y, x in cells:
            out[y, x] = air
    movers.sort(key=lambda m: -max(y for y, x in m[1]))

    def ok(cells, d):
        for y, x in cells:
            ny = y + d
            if ny >= H - 1 or occupied[ny, x]:
                return False
            # need a one-row gap above static ground (grid edge counts)
            if ny + 1 < H and static[ny + 1, x]:
                return False
            if ny + 1 >= H - 1 and not static[H - 1, x] and ny + 1 > H - 1:
                return False
        return True

    for col, cells in movers:
        d = 0
        while ok(cells, d + 1):
            d += 1
        for y, x in cells:
            out[y + d, x] = col
            occupied[y + d, x] = True
        emit(out.copy(), f"Object of colour {col} falls {d} rows, stopping one row above the ground or on a fallen object.")
    emit(out.copy(), "All loose objects have settled.")
    return out
